// Shared function to handle both GET and HEAD requests
async function handlePMTilesRequest(
  request: NextRequest,
  params: Promise<{ path: string[] }>,
  isHeadRequest: boolean = false
) {
  try {
    const resolvedParams = await params
    const path = resolvedParams.path.join('/')
    
    let gcsUrl: string
    
    // Check for H3 PMTiles format: h3_pfas_2023_res10.pmtiles
    const h3Match = path.match(/h3_pfas_(\d{4})_res(\d+)\.pmtiles/)
    if (h3Match) {
      const [, year, resolution] = h3Match
      
      // Get the latest timestamp for this year/resolution combination
      const latestTimestamp = await getLatestH3Timestamp(year, resolution)
      if (!latestTimestamp) {
        return NextResponse.json(
          { error: `H3 PMTiles not found for year ${year} resolution ${resolution}` },
          { status: 404 }
        )
      }
      
      gcsUrl = `${GCS_BASE_URL}/h3_pfas_${year}_res${resolution}/${latestTimestamp}/h3_pfas_${year}_res${resolution}.pmtiles`
    }
    // Check for BNBO PMTiles format: bnbo_areas.pmtiles
    else if (path === 'bnbo_areas.pmtiles') {
      // BNBO PMTiles are stored directly in the pmtiles directory
      gcsUrl = `https://storage.googleapis.com/${BUCKET_NAME}/pmtiles/bnbo_areas.pmtiles`
    }
    // Check for Kommune PMTiles format: kommune_pfas_2023.pmtiles
    else {
      const kommuneMatch = path.match(/kommune_pfas_(\d{4})\.pmtiles/)
      if (!kommuneMatch) {
        return NextResponse.json(
          { error: 'Invalid PMTiles path format. Expected h3_pfas_YYYY_resN.pmtiles, kommune_pfas_YYYY.pmtiles, or bnbo_areas.pmtiles' },
          { status: 400 }
        )
      }
      
      const [, year] = kommuneMatch
      
      // Validate year
      const validYears = ['2015', '2016', '2017', '2018', '2019', '2020', '2021', '2022', '2023']
      if (!validYears.includes(year)) {
        return NextResponse.json(
          { error: `Kommune PMTiles not found for year ${year}` },
          { status: 404 }
        )
      }
      
      // Get the latest timestamp for this year
      const latestTimestamp = await getLatestKommuneTimestamp(year)
      if (!latestTimestamp) {
        return NextResponse.json(
          { error: `Kommune PMTiles not found for year ${year}` },
          { status: 404 }
        )
      }
      
      gcsUrl = `${GCS_BASE_URL}/kommune_pfas_${year}/${latestTimestamp}/kommune_pfas_${year}.pmtiles`
    }
    
    // Handle range requests for PMTiles
    const range = request.headers.get('range')
    
    const headers: Record<string, string> = {
      'Accept-Ranges': 'bytes',
      'Cache-Control': `public, max-age=${CACHE_DURATION}`,
    }
    
    if (range) {
      headers['Range'] = range
    }
    
    // Use HEAD method for HEAD requests, GET for GET requests
    const response = await fetch(gcsUrl, { 
      method: isHeadRequest ? 'HEAD' : 'GET',
      headers 
    })
    
    if (!response.ok) {
      return NextResponse.json(
        { error: `Failed to fetch PMTiles from GCS: ${response.status}` },
        { status: response.status }
      )
    }
    
    // Copy response headers
    const responseHeaders: Record<string, string> = {
      'Content-Type': 'application/octet-stream',
      'Accept-Ranges': 'bytes',
      'Cache-Control': `public, max-age=${CACHE_DURATION}`,
    }
    
    // Copy range-related headers if present
    if (response.headers.get('content-range')) {
      responseHeaders['Content-Range'] = response.headers.get('content-range')!
    }
    if (response.headers.get('etag')) {
      responseHeaders['ETag'] = response.headers.get('etag')!
    }
    if (response.headers.get('last-modified')) {
      responseHeaders['Last-Modified'] = response.headers.get('last-modified')!
    }
    if (response.headers.get('content-length')) {
      responseHeaders['Content-Length'] = response.headers.get('content-length')!
    }
    
    // For HEAD requests, return empty body with headers
    if (isHeadRequest) {
      return new NextResponse(null, {
        status: response.status,
        headers: responseHeaders,
      })
    }
    
    // For GET requests, return the actual file content
    const buffer = await response.arrayBuffer()
    responseHeaders['Content-Length'] = buffer.byteLength.toString()
    
    return new NextResponse(buffer, {
      status: response.status,
      headers: responseHeaders,
    })
  } catch (error) {
    console.error('PMTiles proxy error:', error)
    
    return NextResponse.json(
      { 
        error: 'Failed to fetch PMTiles',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    )
  }
}

// Export GET handler
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> }
) {
  return handlePMTilesRequest(request, params, false)
}

// Export HEAD handler
export async function HEAD(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> }
) {
  return handlePMTilesRequest(request, params, true)
}